class HashTable:
    def __init__(self):
        self.buckets = [[] for _ in range(8)]
        self.size = 0
    def _bucket(self, key):
        return self.buckets[hash(key) % len(self.buckets)]
    def put(self, key, value):
        bucket = self._bucket(key)
        for pair in bucket:
            if pair[0] is key or pair[0] == key:
                pair[1] = value
                return
        bucket.append([key, value])
        self.size += 1
        if self.size > len(self.buckets) * 0.75:
            old = self.buckets
            self.buckets = [[] for _ in range(2 * len(old))]
            for entries in old:
                for pair in entries:
                    self._bucket(pair[0]).append(pair)
    def get(self, key):
        for stored_key, value in self._bucket(key):
            if stored_key is key or stored_key == key:
                return value
        raise KeyError(key)
    def delete(self, key):
        bucket = self._bucket(key)
        for index, pair in enumerate(bucket):
            if pair[0] is key or pair[0] == key:
                del bucket[index]
                self.size -= 1
                return
        raise KeyError(key)

h = HashTable()
for i in range(30):
    h.put(i, i * i)
h.put(0, 'updated')
assert h.get(0) == 'updated' and h.size == 30
h.delete(0)
assert h.get(29) == 841 and h.size == 29
```
键必须可哈希，并遵守相等的键具有相同哈希值且存储期间哈希不变的契约。平均操作 O(1)，恶意冲突时可退化为 O(n)，一次扩容 O(n)。它不是并发或持久化容器，实际业务优先标准 dict。

