    def watermark():return min((maxima[s]for s in active),default=float('inf'))-window
    for event in events:
        source=event.get('source')
        if source not in active:raise ValueError('unknown or ended source')
        if event.get('end')is True:
            active.remove(source)
        else:
            time=event.get('time')
            if type(time)is not int:raise ValueError('time')
            record={'source':source,'time':time,'value':event.get('value')}
