import threading,queue,json,time,traceback
class Pipeline:
    def __init__(self,path,capacity,start=True,writer=None):
        if type(capacity)is not int or capacity<=0:raise ValueError('capacity')
        self.path=path;self.q=queue.Queue(capacity);self.writer=writer
        self.lock=threading.Lock();self.accepted=self.written=self.dropped=0
        self.failure=None;self.closed=False;self.started=False;self.sentinel=object()
        self.thread=threading.Thread(target=self._listen,daemon=True)
        if start:self._start()
    def _start(self):
        if not self.started:self.started=True;self.thread.start()
    def emit(self,level,message,exc_info=None):
        if not isinstance(level,str)or not isinstance(message,str):raise TypeError('record')
        record={'level':level,'message':message,'exception':''.join(traceback.format_exception(*exc_info))if exc_info else None}
        with self.lock:
            if self.closed:raise RuntimeError('closed')
            if self.failure is not None:self.dropped+=1;return False
            try:self.q.put_nowait(record)
            except queue.Full:self.dropped+=1;return False
            self.accepted+=1;return True
    def _listen(self):
        try:
            with open(self.path,'w',encoding='utf-8',newline='')as f:
                while True:
                    item=self.q.get()
                    if item is self.sentinel:break
                    if self.writer:self.writer(item,f)
                    else:f.write(json.dumps(item,ensure_ascii=False)+'\n');f.flush()
                    with self.lock:self.written+=1
        except Exception as e:
            with self.lock:self.failure=type(e).__name__+': '+str(e)
    def _stats(self):
        with self.lock:return {'accepted':self.accepted,'written':self.written,'dropped':self.dropped,'pending':self.accepted-self.written,'failure':self.failure}
    def close(self,timeout=2):
        if self.closed and not self.thread.is_alive():return self._stats()
        with self.lock:self.closed=True
        self._start();deadline=time.monotonic()+timeout
        while self.thread.is_alive():
            remaining=deadline-time.monotonic()
            if remaining<=0:raise TimeoutError('listener')
            try:self.q.put(self.sentinel,timeout=min(.02,remaining));break
            except queue.Full:continue
        self.thread.join(max(0,deadline-time.monotonic()))
        if self.thread.is_alive():raise TimeoutError('listener')
        return self._stats()
```

实现说明：实现Pipeline(path,capacity,start=True,writer=None)。emit(level,message,exc_info=None)只接受字符串，非阻塞入队，满或监听者已失败计dropped并返回False，成功计accepted；exc_info变为可序列化exception文本。后台单监听者逐条写JSONL并计written，writer(record,file)可注入故障。close(timeout=2)停止接收，确保启动并排空已接收数据或报告failure/pending，返回accepted/written/dropped/pending/failure；listener卡住需TimeoutError，不能伪报成功。重复close返回同统计，close后emit抛RuntimeError。仅限有界writer，此题不强制终止任意线程。

原理补充（保留原题）：
