import multiprocessing,struct,base64,json,sys,pathlib
from multiprocessing import shared_memory
HEADER=struct.Struct('!4sBBI')
def consume(name,index,fail_index,results):
    segment=None
    try:
        segment=shared_memory.SharedMemory(name=name)
        if index==fail_index:raise RuntimeError('consumer failed')
        magic,version,ready,length=HEADER.unpack(bytes(segment.buf[:HEADER.size]))
        if magic!=b'OFSM'or version!=1 or length>len(segment.buf)-HEADER.size:raise ValueError('layout')
        if ready!=1:raise ValueError('not-ready')
        payload=bytes(segment.buf[HEADER.size:HEADER.size+length])
        results.put({'index':index,'ok':True,'payload':base64.b64encode(payload).decode()})
    except Exception as e:results.put({'index':index,'ok':False,'error':str(e)})
    finally:
        if segment is not None:segment.close()
def owner(config):
    payload=base64.b64decode(config['payload'],validate=True)
    if len(payload)>4096:raise ValueError('payload too big')
    segment=shared_memory.SharedMemory(create=True,size=HEADER.size+len(payload))
    context=multiprocessing.get_context('spawn');results=context.Queue();children=[];name=segment.name
    try:
        segment.buf[:HEADER.size]=HEADER.pack(b'OFSM',config.get('version',1),int(config.get('ready',True)),len(payload))
        segment.buf[HEADER.size:]=payload
        for index in range(2):
            p=context.Process(target=consume,args=(name,index,config.get('fail_index'),results));p.start();children.append(p)
        rows=[results.get(timeout=5)for _ in children]
        for p in children:
            p.join(timeout=3)
            if p.is_alive()or p.exitcode!=0:raise RuntimeError('consumer exit')
        return {'name':name,'results':sorted(rows,key=lambda r:r['index'])}
    finally:
        for p in children:
            if p.is_alive():p.terminate()
            p.join()
        results.close();results.join_thread()
        segment.close();segment.unlink()
if __name__=='__main__':
    config=json.loads(pathlib.Path(sys.argv[1]).read_text())
    pathlib.Path(sys.argv[2]).write_text(json.dumps(owner(config)),encoding='utf-8')
```

实现说明：task.py CLI接收input.json与result.json。owner创建SharedMemory，布局!4sBBI为magic OFSM、version、ready、payload长度，再存base64解码payload（<=4096字节）。spawn两个消费者，消费者验证version=1和ready=1后读取并回传base64；每个消费者finally只close，禁止unlink。可用fail_index模拟消费者错误。owner收齐结果、join后finally close+unlink；输出name与按index排序results。仅限定同一spawn进程家族Python3.11，不宣称覆盖任意独立进程resource tracker差异。

原理补充（保留原题）：
交付共享段名称、尺寸、数据布局版本、创建者与使用者租约，区分本进程关闭映射与全局取消名字的生命周期。共享内存不自带并发写协议，应定义单写者或锁以及记录完成标记，不能让消费者读取半批数据。不同启动关系及Python版本下resource tracker行为需核对，避免某独立进程退出时提前删除仍被其他进程使用的共享段。验收创建者崩溃、消费者晚到、重复清理、布局不匹配和异常退出，要求没有非法访问或无限泄漏。失败停止新读写并按租约与登记表确认最后使用者，再由指定清理者处理；不能遍历系统共享内存任意删除，也不能只凭名称存在断言内容属于本批次。

